head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil50100n";
scwin.chkIsurCd = "";
scwin.agnccomMbr = 1;
scwin.upd_attachFiles = null;
scwin.upd_attachFiles_2 = null;
scwin.upd_attachFiles_3 = null;
scwin.upd_attachFiles_4 = null;
scwin.leadcomList = undefined;
scwin.bzRegNo = null;
scwin.delListAgnccomMbr = null;
scwin.checkListAgnccom = null;
scwin.delay = null;
