///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — loadTp, uploadCode, isOk

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_remk", attr: "label", fn: function () { return String(dma_detailData.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_loadTp", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '0'); } }, { id: "btn_downloadFile", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '1'); } }, { id: "if_loadTp_3", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '2' || (dma_pageContext.get("loadTp") ?? "") === '3'); } }, { id: "if_loadTp_4", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '0'); } }, { id: "btn_downloadFile_3", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '1'); } }, { id: "if_loadTp_6", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '2' || (dma_pageContext.get("loadTp") ?? "") === '3'); } }, { id: "if_loadTp_7", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '3'); } }, { id: "btn_doDelete", fn: function(){ return ((dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='30'); } }, { id: "btn_goEditForm", fn: function(){ return ((dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='35'||(dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='36'); } }, { id: "btn_goEditForm", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '1'); } }, { id: "btn_doSave", fn: function(){ return ((String(((dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())) == null ? '' : ((dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })()))).length === 0)||(dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='30'||(dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='35'||(dma_detailData.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "detailData.listProcsStatCd"); })())==='37'); } }, { id: "btn_doSave", fn: function(){ return ((dma_pageContext.get("loadTp") ?? "") === '0'||(dma_pageContext.get("loadTp") ?? "") === '2' || (dma_pageContext.get("loadTp") ?? "") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "btn_downloadFile", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "btn_downloadFile_2", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "btn_downloadFile_3", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } },
        { childId: "btn_downloadFile_4", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        form = (document.clmSchdlNotiForm || { elements: [] });
        loadTp = 'null';
        await scwin.checkSave();
        scwin.checkIsurCd();
        const remk = $c.util.getComponent('txa_remk').getValue();
        scwin.setLength(remk, 'divRemk', '2000');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50100n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil50100n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
