/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {*} corpRegNo corpRegNo
 * @param {*} bzRegNo bzRegNo
 * @param {String} comNm comNm
 * @param {String} foundDd foundDd
 * @param {*} secugrp_id secugrp_id
 * @param {*} spot_isu_trd_mkt_tp_cd spot_isu_trd_mkt_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, corpRegNo, bzRegNo, comNm, foundDd, secugrp_id, spot_isu_trd_mkt_tp_cd) {
    if ('' !== comNm) {
        $c.util.getComponent("ipt_chkNm").setValue(comNm);
    } else {
        await $c.win.alert('선택하신 법인의 회사명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if (('' !== isurCd) && (isurCd.length === 5)) {
        $c.util.getComponent("ipt_chkCd").setValue(isurCd);
    } else {
        await $c.win.alert('선택하신 법인의 고유코드가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if (('' !== bzRegNo) && (bzRegNo.length === 10)) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(bzRegNo.substring(5));
    } else {
        if (secugrp_id === 'FS') {
            await $c.win.alert('선택하신 외국법인의 사업자등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '직접 입력해주시기 바랍니다.');
            $c.util.getComponent('ipt_bzRegNo1').readOnly = false;
            $c.util.getComponent('ipt_bzRegNo2').readOnly = false;
            $c.util.getComponent('ipt_bzRegNo3').readOnly = false;
        } else {
            await $c.win.alert('선택하신 법인의 사업자등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
            return;
        }
    }
    $c.util.getComponent("cal_foundDd").setValue(foundDd);
    $c.util.getComponent("slc_secugrpId").setValue(secugrp_id);
    $c.util.getComponent("slc_ldMktTpCd").setValue("6");
};

/**
 * @method
 * @name canAddAgnccomMbr
 * @description can Add Agnccom Mbr 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.canAddAgnccomMbr = async function () {
    const obj = $c.util.getComponent('slc_listAgnccomMbrNo');
    const len = obj.length;
    if (len < 11) {
        for (let i = 0; i < len; i++) {
            if (obj[i].value === '') {
                await $c.win.alert('하나 이상의 지정자문인을 선택해야 합니다.');
                return false;
            }
        }
    } else {
        if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
            await $c.win.alert('하나 이상의 지정자문인을 선택해야 합니다.');
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name addListAgnccomMbr
 * @description add List Agnccom Mbr 처리
 * @param {*} seqNum seqNum
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addListAgnccomMbr = async function (seqNum) {

    if(await scwin.canAddAgnccomMbr()){
        const ver = scwin.agnccomMbr + 1;
        const language=$c.util.getComponent("agnccomMbrTable");
        let txt ='';
        txt+="				<select name='listAgnccomMbrNo'  class='form_select' onchange='checkListAgnccom(this);'>";
        txt+="				<option value=''>--- 선택 ---</option>";

        for (let i1 = 0; i1 < dlt_leadcomListKonex.getRowCount(); i1++) {
            txt+='		<option value="${leadcomListKonex[__i1].code}${(readDataVO.listAgnccomMbrNo2 == entity.code )?\'selected\':\'\'}">${leadcomListKonex[__i1].name}</option>';
        }

        txt+="              </select>    ";
        txt+="				<a href='#' onclick='delListAgnccomMbr("+ver+");return false;'><img src='/img/main/x.gif' alt='삭제'></img></a> ";

        scwin.agnccomMbr++;

        // 새로 생성
        const addedDiv = document.createElement("div");

        addedDiv.id = "added_Mbr"+scwin.agnccomMbr;
        addedDiv.innerHTML = txt;
        language.appendChild(addedDiv);
    }

};

function delListAgnccomMbr(seqNum) {
    const mbr = $c.util.getComponent("agnccomMbrTable");
    if (scwin.agnccomMbr > 0) {
        const addedDiv = $c.util.getComponent("added_Mbr" + seqNum);
        mbr.removeChild(addedDiv);
        scwin.agnccomMbr--;
    } else {
        (document.form || { elements: [] }).reset();
    }
}

/**
 * @method
 * @name chkId
 * @description chk Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkId = function () {
    const bzProcsNo = $c.util.getComponent('ipt_bzProcsNo').getValue();
    const newConNm = '' + dma_detailData.get("new_com_nm") + '';
    const isurCd = $c.util.getComponent('ipt_chkCd').getValue();
    const isurNm = $c.util.getComponent('ipt_chkNm').getValue();
    $.ajax({ type: "POST", url: "/listInvstg/clmSchdlNoti.do", data: { method: "chkIsurCd", bzProcsNo: bzProcsNo, isurCd: isurCd }, success: async function(data) {
                try {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    scwin.chkIsurCd = result.chkIsurCd;
                    return scwin.chkIsurCd;
                    if (result.chkIsurCd === 'N') {
                        scwin.chkIsurCd = result.chkIsurCd;
                        return scwin.chkIsurCd;
                    }
                } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil50100n' });
                    await $c.win.alert("시스템 처리중에 문제가 발생하였습니다. 시스템담당자(02-3774-9572~3)에게 문의하시길 바랍니다.1");
                }
            }, complete: function() {
                scwin.delay = false;
            } });
};

/**
 * @method
 * @name doSave
 * @description do Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doSave = async function () {
    const loadTp = 'null';
    if (loadTp !== '0') {
        scwin.chkId();
    }
    if (scwin.chkIsurCd === 'N') {
        await $c.win.alert('청구계획통보 발행기관정보(' + isurNm + ')와  ID배정의 발행기관정보(' + newConNm + ')가 다릅니다.\n' + '시스템담당자(02-3774-9572~3)에게 문의하시길 바랍니다.');
    } else {
        form.action = '/listInvstg/clmSchdlNoti.do';
        if (loadTp === '0') {
            $c.util.getComponent('dma_doSaveReq').set('method', 'writeN');
        }
        if (loadTp === '2' || loadTp === '3') {
            $c.util.getComponent('dma_doSaveReq').set('method', 'editN');
        }
        const mbrNo = $c.util.getComponent('slc_listAgnccomMbrNo').getValue();
        if (await scwin.checkValue()) {
            if (mbrNo.length === 2) {
                $c.util.getComponent("dma_chkIdReq").set("speclListTpCd", $c.util.getComponent('slc_listAgnccomMbrNo').getValue());
            }
            const nr = await scwin.tx_doSave();
            if (nr && nr.responseJSON && nr.responseJSON.success === true) {
                $c.win.moveUrl("/jldfil50100/jldfil50100.xml", { "method": 'writeN', "speclListTpCd": $c.util.getComponent('slc_listAgnccomMbrNo').getValue() });
            }
        }
    }
};

