/**
 * @method
 * @name checkListAgnccomMbrNo
 * @description check List Agnccom Mbr No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkListAgnccomMbrNo = async function () {
    const obj = $c.util.getComponent('slc_listAgnccomMbrNo');
    const len = obj.length;
    if (len < 11) {
        for (let i = 0; i < len; i++) {
            if (obj[i].value === '') {
                obj[i].disabled = true;
            }
        }
    }
    if (len > 11) {
        if ((obj.getValue() == null ? '' : String(obj.getValue())) === '') {
            await $c.win.alert('하나 이상의 지정자문인을 선택해야 합니다.');
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    $c.util.getComponent('dma_doSaveReq').set('bzRegNo', $c.util.getComponent('ipt_bzRegNo1').getValue()+ $c.util.getComponent('ipt_bzRegNo2').getValue()+ $c.util.getComponent('ipt_bzRegNo3').getValue());
    if ($c.util.getComponent('slc_ldMktTpCd').getValue()!== "6") {
        await $c.win.alert("상장시장을 반드시 선택하시기 바랍니다.");
        return false;
    }
    if (($c.util.getComponent('ipt_chkCd').getValue() == null ? '' : String($c.util.getComponent('ipt_chkCd').getValue())) === '') {
        await $c.win.alert('발행기관을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('slc_prelmInvstgComTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_prelmInvstgComTpCd').getValue())) === '') {
        await $c.win.alert('기업구분을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('slc_listClssCd').getValue() == null ? '' : String($c.util.getComponent('slc_listClssCd').getValue())) === '') {
        await $c.win.alert('상장유형을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('slc_clmSchdlYymm').getValue() == null ? '' : String($c.util.getComponent('slc_clmSchdlYymm').getValue())) === '' || $c.util.getComponent('slc_clmSchdlYymm').getValue()=== "00") {
        await $c.win.alert('신청예정년월일을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_designAudtrNm').getValue() == null ? '' : String($c.util.getComponent('ipt_designAudtrNm').getValue())) === '') {
        await $c.win.alert('(지정)감사인을 입력하셔야 합니다.');
        return false;
    }
    if ($c.util.getComponent('slc_audtOpinTpCd').getValue() === "") {
        await $c.win.alert('감사의견을 선택하셔야 합니다.');
        return false;
    }
    if ($c.util.getComponent('slc_acntclsMm').getValue()=== "--") {
        await $c.win.alert('결산기 월을 선택하셔야 합니다.');
        return false;
    }
    if ($c.util.getComponent('slc_acntclsDd').getValue()=== "--") {
        await $c.win.alert('결산기 일을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_indCodeNm').getValue() == null ? '' : String($c.util.getComponent('ipt_indCodeNm').getValue())) === '' || ($c.util.getComponent('ipt_stdIndCd').getValue() == null ? '' : String($c.util.getComponent('ipt_stdIndCd').getValue())) === '') {
        await $c.win.alert('업종(코드)를 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('cal_foundDd').getValue() == null ? '' : String($c.util.getComponent('cal_foundDd').getValue())) === '') {
        await $c.win.alert('설립년월을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_netincmAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_netincmAmt').getValue())) === '') {
        await $c.win.alert('당기순이익을 입력하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_sales').getValue() == null ? '' : String($c.util.getComponent('ipt_sales').getValue())) === '') {
        await $c.win.alert('매출액을 입력하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_totAsstAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_totAsstAmt').getValue())) === '') {
        await $c.win.alert('총자산금액을 입력하셔야 합니다.');
        return false;
    }
    if (!await scwin.checkListAgnccomMbrNo()) {
        return false;
    }
    for (let i = 0; i < $c.util.getComponent('slc_secugrpId').length; i++) {
        if ($c.util.getComponent('slc_secugrpId')[i].selected === true) {
            if (i === 0) {
                await $c.win.alert('증권그룹을 선택하셔야 합니다.');
                return false;
            }
        }
    }
    $c.util.getComponent('dma_doSaveReq').set('acntclsMmdd', $c.util.getComponent('slc_acntclsMm').getValue()+ $c.util.getComponent('slc_acntclsDd').getValue());
    return true;
};

